    const sheet = ui.sheetId();
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import java.time.format.DateTimeParseException;
import net.officefloor.hq.app.asof.AsOfReader;
import net.officefloor.hq.app.period.Period;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.setting.Role;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.hq.app.voidreason.VoidReasonRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

/**
 * Moves the claim to the action's status; refused (400) when the claim's status does not allow it.
 * Settling or approving gives an unnumbered claim the sheet's next number (an OPEN, PENDING or REVIEW claim has none;
 * one numbered before keeps its number); a voided claim keeps its number (it is never reused). While the
 * sheet's period numbering from date is set and its today is on or after it, settling instead gives the claim the next
 * number within the period containing its due-by (P1-1, P1-2, ...), or within the claims in no period (X-1, ...).
 * Opening, settling and voiding are refused (400) to a role the sheet's permission matrix does not allow them.
 * Opening records the user who opened it; that user cannot settle it (four eyes). Nor can the user who last edited
 * it (through its editor or its row's amount entry) settle or approve it. A deferred claim cannot be settled.
 * Settled as of a date (on or before the sheet's today; refused after it, or when the claim did not exist then),
 * the due fixed is the claim's due as it stood at the end of that date, as the as-of view works it out.
 * Settling fixes the claim's due at the greater of the sheet's floor in force on its date and its figure — at its person's grade's rate in force on the claim's date,
 * rounded by its policy date, or, when a statement bound the claim, the figure it was bound to — plus the late charge it has then, if overdue, frozen in; with no
 * figure it stays live. A clerk settling a claim whose due is above the clerk limit in force (its person's grade's own on the sheet's today, when it has one, else the sheet's) (a due of n/a is within any
 * limit) makes it PENDING instead, live and unfixed. A claim with no proofs (while the sheet has proof kinds: without a proof of each) whose due is above the proof threshold in force on its date —
 * its person's grade's own, when that grade has one then, else the sheet's — is refused settling or approving — before the clerk limit is considered, so it never goes PENDING.
 * A claim with an empty note whose due (as shown now) is above the sheet's note threshold in force on its date is refused opening.
 * Opening a claim due by a date in a period with a cap is refused while its person already has that many OPEN or PENDING
 * claims due by a date in that period. Opening a claim is refused while its person already has the sheet's maximum of
 * OPEN or PENDING claims (any period). Only a steward — or the claim's person's approver — approves a PENDING claim (fixing its due at its figure —
 * the one its statement bound it to, if any — plus any late charge, at that moment) — not the user who opened it — or rejects it, with a reason, back to OPEN.
 * Only a steward re-settles a SETTLED claim, fixing its due again at the figure it would have today as an open claim
 * bound by no statement (today's rates, grades, floor and late charge); its previous due is kept for the audit.
 * Only a steward voids a SETTLED claim, and only while the sheet's today is within 7 days of its settlement (the
 * status log's latest SETTLED date); it keeps its number and its frozen due, which leaves every total.
 * While the sheet's void reasons list is not empty, a void is refused (400) without a reason chosen from it; a reason
 * not on the list is always refused.
 * Opening a claim whose due (as shown now) is above the sheet's review threshold in force on its date sends it to REVIEW
 * instead, recording who opened it; only a steward reviews it, which opens it (still with no number).
 * While its person is flagged (the sheet's today on or before the flag's until date), only a steward opens a claim.
 * Deleting sets a DRAFT claim aside as DELETED (counting nowhere); restoring makes it a DRAFT again, only while the
 * sheet's today is the day it was deleted (the status log's latest DELETED date).
 */
public class ApplyClaimAction {

    /** How many days after its settlement (the status log's SETTLED date) a steward may still void a SETTLED claim. */
    static final int VOID_SETTLED_DAYS = 7;

    public void apply(@PathVariable("action") String action, @RequestParam("user") String user, @Val Claim claim,
            @Val ClaimActionRequest request, SheetRepository sheets,
            PersonRepository people, RateRepository rates, SettingRepository settings, PeriodRepository periods,
            VoidReasonRepository voidReasons, ClaimRepository claims, ClaimLogRepository logs, AsOfReader asOf, Out<ClaimAction> applied, Out<ClaimNumber> number, Out<PreviousDue> previous, Out<Claim> updated) throws InvalidClaimException {
        decide(action, user, claim, request, sheets, people, rates, settings, periods, voidReasons, claims, logs, asOf,
                applied, number, previous, updated, true);
    }

    /**
     * Refuses the action as {@link #apply} does, else publishes its outcome; without {@code draw}, a settle that would
     * give the claim its number draws none (a check that must change nothing, the sheet's numbering included).
     */
    static void decide(String action, String user, Claim claim,
            ClaimActionRequest request, SheetRepository sheets,
            PersonRepository people, RateRepository rates, SettingRepository settings, PeriodRepository periods,
            VoidReasonRepository voidReasons, ClaimRepository claims, ClaimLogRepository logs, AsOfReader asOf, Out<ClaimAction> applied, Out<ClaimNumber> number, Out<PreviousDue> previous, Out<Claim> updated, boolean draw) throws InvalidClaimException {
        ClaimAction found = ClaimAction.of(action);
        if (found == null) {
            throw new InvalidClaimException("No such claim action: " + action);
        }
        if (!found.allowedFrom(claim.status())) {
            throw new InvalidClaimException("A " + claim.status() + " claim cannot be " + found.to() + ".");
        }
        if ((found == ClaimAction.OPEN || found == ClaimAction.SETTLE || found == ClaimAction.VOID)
                && !settings.find(claim.sheetId()).may(user, action)) {
            throw new InvalidClaimException("The user's role is not allowed to " + action + " a claim.");
        }
        if (found == ClaimAction.OPEN && settings.find(claim.sheetId()).roleOf(user) != Role.STEWARD
                && people.flagOn(claim.sheetId(), claim.personId(), sheets.today(claim.sheetId())) != null) {
            throw new InvalidClaimException("The claim's person is flagged: only a steward may open their claims.");
        }
        if (found == ClaimAction.SETTLE && claim.deferred(sheets.today(claim.sheetId()))) {
            throw new InvalidClaimException("The claim is deferred until " + claim.deferredUntil() + ": it cannot be settled yet.");
        }
        if (found == ClaimAction.SETTLE && user.equals(claim.openedBy())) {
            throw new InvalidClaimException("The user who opened a claim cannot settle it.");
        }
        if (found == ClaimAction.APPROVE && user.equals(claim.openedBy())) {
            throw new InvalidClaimException("The user who opened a claim cannot approve it.");
        }
        if ((found == ClaimAction.SETTLE || found == ClaimAction.APPROVE)
                && user.equals(claims.editedBy(claim.sheetId(), claim.id()))) {
            throw new InvalidClaimException("The user who last edited a claim cannot " + action + " it.");
        }
        if ((found == ClaimAction.APPROVE || found == ClaimAction.REJECT)
                && settings.find(claim.sheetId()).roleOf(user) != Role.STEWARD
                && !user.equals(people.approver(claim.sheetId(), claim.personId()))) {
            throw new InvalidClaimException("Only a steward or the person's approver can " + action + " a pending claim.");
        }
        if (found == ClaimAction.REVIEW && settings.find(claim.sheetId()).roleOf(user) != Role.STEWARD) {
            throw new InvalidClaimException("Only a steward can review a claim.");
        }
        if (found == ClaimAction.RESETTLE && settings.find(claim.sheetId()).roleOf(user) != Role.STEWARD) {
            throw new InvalidClaimException("Only a steward can re-settle a settled claim.");
        }
        if (found == ClaimAction.VOID && claim.status() == ClaimStatus.SETTLED) {
            if (settings.find(claim.sheetId()).roleOf(user) != Role.STEWARD) {
                throw new InvalidClaimException("Only a steward can void a settled claim.");
            }
            LocalDate settledOn = logs.find(claim.sheetId(), claim.id()).stream()
                    .filter((l) -> l.status() == ClaimStatus.SETTLED).map(ClaimLogLine::date)
                    .reduce((a, b) -> b).orElse(null);
            if (settledOn == null || sheets.today(claim.sheetId()).isAfter(settledOn.plusDays(VOID_SETTLED_DAYS))) {
                throw new InvalidClaimException("A settled claim can be voided only within " + VOID_SETTLED_DAYS
                        + " days of its settlement.");
            }
        }
        if (found == ClaimAction.VOID) {
            List<String> reasons = voidReasons.findAll(claim.sheetId());
            if (request.reason().isEmpty() ? !reasons.isEmpty() : !reasons.contains(request.reason())) {
                throw new InvalidClaimException("A void needs a reason chosen from the sheet's void reasons.");
            }
        }
        if (found == ClaimAction.RESTORE) {
            LocalDate deletedOn = logs.find(claim.sheetId(), claim.id()).stream()
                    .filter((l) -> l.status() == ClaimStatus.DELETED).map(ClaimLogLine::date)
                    .reduce((a, b) -> b).orElse(null);
            if (deletedOn == null || !sheets.today(claim.sheetId()).equals(deletedOn)) {
                throw new InvalidClaimException("A deleted claim can be restored only on the day it was deleted.");
            }
        }
        if (found == ClaimAction.REJECT && request.reason().isEmpty()) {
            throw new InvalidClaimException("A reason is required to reject a claim.");
        }
        LocalDate on = found == ClaimAction.SETTLE ? settleOn(claim, request, sheets) : null;
        BigDecimal due = on != null ? settledDueAsOf(claim, on, asOf, sheets, people, rates, settings, claims)
                : found.settles() ? settledDue(found == ClaimAction.RESETTLE ? claim.asOpenUnbound() : claim, sheets, people, rates, settings, claims) : claim.due();
        if (found == ClaimAction.OPEN && (claim.note() == null || claim.note().isBlank())
                && settings.dated(claim.sheetId()).needsNote(claim.date(),
                        ClaimDueNow.of(claim, sheets, people, rates, settings, claims))) {
            throw new InvalidClaimException("The claim's due is above the note threshold: it needs a note to be opened.");
        }
        if (found == ClaimAction.OPEN) {
            checkCap(claim, periods, claims);
            checkMaxOpen(claim, settings, claims);
        }
        if ((found == ClaimAction.SETTLE || found == ClaimAction.APPROVE) && !hasProofs(claim, settings, claims)
                && settings.dated(claim.sheetId()).needsProof(proofGrade(claim, people), claim.date(), due)) {
            throw new InvalidClaimException("The claim's due is above the proof threshold: it needs a proof (of each of the sheet's proof kinds) to be "
                    + (found == ClaimAction.SETTLE ? "settled" : "approved") + ".");
        }
        if (found == ClaimAction.OPEN && settings.dated(claim.sheetId()).needsReview(claim.date(),
                ClaimDueNow.of(claim, sheets, people, rates, settings, claims))) {
            found = ClaimAction.SEND_TO_REVIEW;
        }
        if (found == ClaimAction.SETTLE && !settings.find(claim.sheetId()).maySettle(user, limitGrade(claim, people), due)) {
            found = ClaimAction.PEND;
            due = null;
        }
        String next = found.settles() && claim.number() == null && draw
                ? ClaimNumbers.next(claim, sheets, settings, periods)
                : claim.number();
        applied.set(found);
        previous.set(new PreviousDue(claim.due(), claim.status() == ClaimStatus.SETTLED));
        number.set(new ClaimNumber(next));
        updated.set(claim.withStatus(found.to(), next, due, found == ClaimAction.OPEN || found == ClaimAction.SEND_TO_REVIEW ? user : claim.openedBy()));
    }

    /** Refuses opening the claim when its period's cap on its person's OPEN and PENDING claims is already reached. */
    private static void checkCap(Claim claim, PeriodRepository periods, ClaimRepository claims) throws InvalidClaimException {
        Period period = periods.findAll(claim.sheetId()).stream()
                .filter((p) -> p.cap() != null && claim.dueBy() != null && p.contains(claim.dueBy())).findFirst().orElse(null);
        if (period == null) {
            return;
        }
        long open = claims.findForPerson(claim.sheetId(), claim.personId()).stream()
                .filter((c) -> !c.id().equals(claim.id()) && c.dueBy() != null && period.contains(c.dueBy())
                        && (c.status() == ClaimStatus.OPEN || c.status() == ClaimStatus.PENDING))
                .count();
        if (open >= period.cap()) {
            throw new InvalidClaimException("The person already has " + period.cap() + " open claims in period "
                    + period.name() + ": its cap.");
        }
    }

    /** Refuses opening the claim when its person already has the sheet's maximum of OPEN and PENDING claims. */
    private static void checkMaxOpen(Claim claim, SettingRepository settings, ClaimRepository claims) throws InvalidClaimException {
        Integer max = settings.maxOpen(claim.sheetId());
        if (max == null) {
            return;
        }
        long open = claims.findForPerson(claim.sheetId(), claim.personId()).stream()
                .filter((c) -> !c.id().equals(claim.id())
                        && (c.status() == ClaimStatus.OPEN || c.status() == ClaimStatus.PENDING))
                .count();
        if (open >= max) {
            throw new InvalidClaimException("The person already has " + max + " open claims: the sheet's maximum.");
        }
    }

    /** Whether the claim has the proofs a claim above the proof threshold needs: one of each of the sheet's proof kinds, else any one. */
    static boolean hasProofs(Claim claim, SettingRepository settings, ClaimRepository claims) {
        if (claim.proofs() == 0) {
            return false;
        }
        int photos = claims.photoProofs(claim.sheetId(), claim.id());
        for (String kind : settings.proofKinds(claim.sheetId())) {
            int count = ProofKind.PHOTO.equals(kind) ? photos : claim.proofs() - photos;
            if (count == 0) {
                return false;
            }
        }
        return true;
    }

    /** The grade whose clerk limit the claim falls under: its person's grade (null: no person). */
    static String limitGrade(Claim claim, PersonRepository people) {
        Person person = people.find(claim.sheetId(), claim.personId());
        return person == null ? null : person.grade();
    }

    /** The grade whose proof threshold the claim falls under: its person's grade in force on its date (null: no person). */
    static String proofGrade(Claim claim, PersonRepository people) {
        Person person = people.find(claim.sheetId(), claim.personId());
        return person == null ? null : person.gradeOn(claim.date());
    }

    /** The date the settle is taken as of (null: now); refused after the sheet's today. */
    private static LocalDate settleOn(Claim claim, ClaimActionRequest request, SheetRepository sheets)
            throws InvalidClaimException {
        if (request.on() == null || request.on().isEmpty()) {
            return null;
        }
        LocalDate on;
        try {
            on = LocalDate.parse(request.on());
        } catch (DateTimeParseException e) {
            throw new InvalidClaimException("Not a date to settle as of: " + request.on());
        }
        if (on.isAfter(sheets.today(claim.sheetId()))) {
            throw new InvalidClaimException("A claim cannot be settled as of a date after the sheet's today.");
        }
        return on;
    }

    /**
     * The claim's due as it stood at the end of the date, as the as-of view works it out (every change made while the
     * sheet's today was on or before it, with the date as today); refused when the claim did not exist then.
     */
    private static BigDecimal settledDueAsOf(Claim claim, LocalDate on, AsOfReader asOf, SheetRepository sheets,
            PersonRepository people, RateRepository rates, SettingRepository settings, ClaimRepository claims)
            throws InvalidClaimException {
        Object[] then = asOf.read(claim.sheetId(), on, () -> {
            Claim thenClaim = claims.find(claim.sheetId(), claim.id());
            return thenClaim == null || thenClaim.status() == ClaimStatus.DELETED ? null
                    : new Object[] { ClaimDueNow.of(thenClaim, sheets, people, rates, settings, claims) };
        });
        if (then == null) {
            throw new InvalidClaimException("The claim did not exist on " + on + ": it cannot be settled as of then.");
        }
        return (BigDecimal) then[0];
    }

    private static BigDecimal settledDue(Claim claim, SheetRepository sheets, PersonRepository people,
            RateRepository rates, SettingRepository settings, ClaimRepository claims) {
        return ClaimDueNow.of(claim, sheets, people, rates, settings, claims);
    }
}
package net.officefloor.hq.app.claim;

/**
 * What a status change submits: the reason, for a reject (ignored otherwise; null: none), and the token of the bulk
 * settle a settle is part of (ignored otherwise; null: taken one at a time), and the date a settle is taken as of
 * (ignored otherwise; empty: now, the sheet's today).
 */
public record ClaimActionRequest(String reason, String batch, String on) {

    public ClaimActionRequest(String reason, String batch) {
        this(reason, batch, "");
    }
}
package net.officefloor.hq.app.claim;

/**
 * A change of a claim's status: the status it may start from, the status it ends in, and its audit event. PEND is
 * never asked for by name: it is what a clerk's settle becomes when the due is above the clerk limit. RESETTLE
 * freezes a SETTLED claim again at today's figure. DELETE sets a DRAFT aside as DELETED; RESTORE makes it a DRAFT again,
 * only on the sheet's today it was deleted. SEND_TO_REVIEW is never asked for by name: it is what an open becomes when
 * the due is above the review threshold; REVIEW (a steward's) then opens the claim.
 */
public enum ClaimAction {
    OPEN("open", ClaimStatus.OPEN, "CLAIM_OPENED", ClaimStatus.DRAFT),
    SEND_TO_REVIEW(null, ClaimStatus.REVIEW, "CLAIM_REVIEW", ClaimStatus.DRAFT),
    REVIEW("review", ClaimStatus.OPEN, "CLAIM_REVIEWED", ClaimStatus.REVIEW),
    SETTLE("settle", ClaimStatus.SETTLED, "CLAIM_SETTLED", ClaimStatus.OPEN),
    PEND(null, ClaimStatus.PENDING, "CLAIM_PENDING", ClaimStatus.OPEN),
    APPROVE("approve", ClaimStatus.SETTLED, "CLAIM_APPROVED", ClaimStatus.PENDING),
    REJECT("reject", ClaimStatus.OPEN, "CLAIM_REJECTED", ClaimStatus.PENDING),
    VOID("void", ClaimStatus.VOID, "CLAIM_VOIDED", ClaimStatus.DRAFT, ClaimStatus.OPEN, ClaimStatus.PENDING,
            ClaimStatus.SETTLED, ClaimStatus.REVIEW),
    RESETTLE("resettle", ClaimStatus.SETTLED, "CLAIM_RESETTLED", ClaimStatus.SETTLED),
    DELETE("delete", ClaimStatus.DELETED, "CLAIM_DELETED", ClaimStatus.DRAFT),
    RESTORE("restore", ClaimStatus.DRAFT, "CLAIM_RESTORED", ClaimStatus.DELETED);

    private final String path;
    private final ClaimStatus to;
    private final String event;
    private final ClaimStatus[] from;

    ClaimAction(String path, ClaimStatus to, String event, ClaimStatus... from) {
        this.path = path;
        this.to = to;
        this.event = event;
        this.from = from;
    }

    /** The action named in the path, or null. */
    public static ClaimAction of(String path) {
        for (ClaimAction action : values()) {
            if (action.path != null && action.path.equals(path)) {
                return action;
            }
        }
        return null;
    }

    public boolean allowedFrom(ClaimStatus status) {
        for (ClaimStatus s : from) {
            if (s == status) {
                return true;
            }
        }
        return false;
    }

    public ClaimStatus to() {
        return to;
    }

    public String event() {
        return event;
    }

    /** Whether the action fixes the claim's due: settling, approving a pending settle, or re-settling. */
    public boolean settles() {
        return to == ClaimStatus.SETTLED;
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/**
 * Records the claim's status change, with its person's name; runs only once the change has been allowed.
 * Settling and approving also record the due fixed (n/a when the grade had no rate); a settle taken as of a date records that date (on=) after its due; rejecting records its reason;
 * a steward's review records CLAIM_REVIEWED (no number) then CLAIM_OPENED with the number it gave;
 * re-settling records the previous due and the new one; voiding a SETTLED claim records the frozen due it reverses; voiding with a reason records it last.
 */
public class AuditClaimAction {
    public void audit(@Val ClaimAction action, @Val ClaimNumber number, @Val Claim claim, @Val ClaimActionRequest request,
            @Val PreviousDue previous,
            PersonRepository people,
            @RequestParam("user") String user, Audit audit) {
        Person person = people.find(claim.sheetId(), claim.personId());
        if (action == ClaimAction.REVIEW) {
            audit.record(action.event() + " sheet=" + claim.sheetId() + " by=" + user + " person="
                    + (person == null ? "" : person.name()) + " amount=" + claim.amount().setScale(2).toPlainString()
                    + " date=" + claim.date());
            action = ClaimAction.OPEN;
        }
        audit.record(action.event() + " sheet=" + claim.sheetId() + " by=" + user + " person="
                + (person == null ? "" : person.name()) + " amount=" + claim.amount().setScale(2).toPlainString()
                + " date=" + claim.date() + Claim.auditNumber(number.value())
                + (action == ClaimAction.RESETTLE
                        ? " old=" + figure(previous.value()) + " new=" + figure(claim.due())
                        : action.settles() ? " due=" + figure(claim.due()) : "")
                + (action == ClaimAction.SETTLE && !request.on().isEmpty() ? " on=" + request.on() : "")
                + (action == ClaimAction.REJECT ? " reason=" + request.reason() : "")
                + (action == ClaimAction.VOID && previous.settled() ? " reversed=" + figure(previous.value()) : "")
                + (action == ClaimAction.VOID && !request.reason().isEmpty() ? " reason=" + request.reason() : ""));
    }

    private static String figure(BigDecimal due) {
        return due == null ? "n/a" : due.setScale(2).toPlainString();
    }
}
# Change a claim's status: open (DRAFT -> OPEN), settle (OPEN -> SETTLED), approve (PENDING -> SETTLED),
# reject (PENDING -> OPEN, with the body's reason), void (DRAFT, OPEN or PENDING -> VOID),
# delete (DRAFT -> DELETED) or restore (DELETED -> DRAFT, only on the sheet's today it was deleted).
# A steward also voids a SETTLED claim within 7 days of its settlement (the status log's SETTLED date).
# A change its status does not allow is refused (400) and writes nothing.
# A claim dated inside a closed period is refused (400).
# A clerk settling a claim whose due is above the sheet's clerk limit makes it PENDING; a steward settles anything.
# Only a steward approves or rejects; the user who opened the claim cannot approve it.
# Only a steward re-settles (resettle: SETTLED -> SETTLED), freezing the claim again at today's figure as an open, unbound claim.
# While the sheet's void reasons list is not empty, a void needs the body's reason chosen from it (400 otherwise).
# A settle (or re-settle) with the body's batch token is part of a bulk settle: the claim takes that bulk settle's
# batch number (the sheet's next the first time), SETTLED or PENDING; a settle taken one at a time has none, and a
# re-settle taken one at a time keeps the batch the claim has.
# A claim that ends SETTLED (settled, approved or re-settled) notifies each user watching its person.
